head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > parent]<br/>호출한 화면의 부모 페이지의 Scope 객체를 반환합니다.",
    "validation" : [
        "호출한 화면의 부모 페이지의 Scope 객체를 반환해야 합니다.",
        "opener 가 존재하면(팝업에서 호출) opener 의 Scope 객체를 반환하고, opener 가 없고 parent 가 존재하면(iframe/WFrame 에서 호출) parent 의 Scope 객체를 반환해야 합니다.",
        "현재 화면이 'iframePopup', 'browserPopup' 팝업인 경우 별도의 Window 객체에 생성되므로 팝업의 최상위 페이지의 Scope 객체를 반환해야 합니다.",
        "호출하는 화면의 WFrame scope 속성이 true 로 설정되지 않은 경우 부모 화면의 최상위 페이지의 Scope 객체가 반환되어야 합니다.",
        "WFrame scope 속성이 true 로 설정된 자식 WFrame 에서 호출 시 해당 부모 WFrame 의 Scope 객체가 반환되어야 합니다."
    ]
}


// 최상위 화면의 scwin 함수 ($p.parent() 반환 Scope 를 통해 호출됨)
scwin.getMainPageInfo = function () {
    return "최상위 페이지 scwin.getMainPageInfo() 호출 성공";
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openBrowserPopup_onclick = function () {
    var options = {
        id: "parent_browserPopup",
        type: "browserPopup",
        width: "520px",
        height: "260px",
        top: "100px",
        left: "100px",
        popupName: "parent browserPopup 테스트",
        modal: false
    };

    $p.openPopup("/sample/common_link/p_parent_popup.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (browserPopup) - 팝업 내부에서 결과 확인");
}
